# Generated by scripts/generate_cloud_validators.py; do not edit.
"""Read-only experimental Sunday intelligence inside the existing research app."""

import json

import joblib
import pandas as pd
import streamlit as st

from stage1b.data import MARKETS

from season_intelligence.experiment import DEFAULT
from season_intelligence.probability import quoted_value
from .cloud_intelligence import validate


@st.cache_data(show_spinner=False)
def load(fingerprint):
    validate(DEFAULT)
    return (
        pd.read_parquet(DEFAULT / "sunday_forecasts.parquet"),
        pd.read_csv(DEFAULT / "sunday_shortlist.csv"),
        json.loads((DEFAULT / "selection.json").read_text()),
    )


def render(release):
    with st.expander("Sunday player-workload and probability research", expanded=True):
        try:
            marker = DEFAULT / "manifest.json"
            frame, shortlist, choices = load(
                (marker.stat().st_mtime_ns, marker.stat().st_size)
            )
        except (OSError, ValueError, KeyError, AssertionError):
            st.info(
                "Sunday intelligence unavailable or failed integrity checks. Certified forecasts are unchanged."
            )
            return
        if release["release_id"] != "research-week11-frozen-20261120-r2":
            st.info(
                "This frozen research overlay belongs to Week11; it is not the current selected release."
            )
            return
        now = pd.Timestamp.now(tz="UTC")
        eligible = pd.to_datetime(frame.kickoff_at, utc=True).gt(
            now + pd.Timedelta(minutes=60)
        )
        frame = frame[eligible]
        shortlist = shortlist[shortlist.game_id.isin(frame.game_id)]
        st.warning(
            "EXPERIMENTAL — NOT PROMOTED. No verified bookmaker odds or betting edge. These probabilities are conditional on participation; missing/DNP outcomes are not assumed zero. Existing Top Picks and pricing remain unchanged."
        )
        if frame.empty:
            st.info(
                "No frozen Sunday forecasts remain before T−60. No expired forecast is presented as current."
            )
            return
        st.caption(
            f"{len(frame)} eligible player-market forecasts · {frame.game_id.nunique()} fixtures. Research priority uses historical calibration and recent participation, not invented EV."
        )
        st.dataframe(
            shortlist[
                [
                    "player",
                    "team",
                    "opponent",
                    "market",
                    "baseline",
                    "enhanced_candidate",
                    "hypothetical_line",
                    "p_over",
                    "q05",
                    "q95",
                ]
            ]
            .rename(
                columns={
                    "hypothetical_line": "Hypothetical line",
                    "p_over": "Research P(over)",
                }
            )
            .round(3),
            hide_index=True,
            width="stretch",
        )
        game = st.selectbox(
            "Sunday intelligence fixture",
            sorted(frame.game_id.unique()),
            key="season_intel_fixture",
        )
        current = frame[frame.game_id.eq(game)]
        identity = st.selectbox(
            "Player and prop",
            list(current.index),
            format_func=lambda i: (
                f"{current.loc[i, 'player']} · {current.loc[i, 'market']}"
            ),
            key="season_intel_player",
        )
        r = current.loc[identity]
        c = choices[r.market]
        st.markdown(f"**{r.player} · {r.market.replace('_', ' ')}**")
        st.write(
            f"Certified baseline {r.baseline:.2f} → experimental candidate {r.enhanced_candidate:.2f} ({r.candidate_delta:+.2f}). Not selected or certified."
        )
        st.write(r.explanation)
        st.caption(
            f"90% research outcome interval {r.q05:.0f}–{r.q95:.0f}. 2025 point gate: {c['retrospective_point_gate']}; probability gate: {c['retrospective_probability_gate']}. Previously inspected data is not an independent final test."
        )
        st.caption(
            f"Built {r.prediction_at}; feature cutoff {r.feature_cutoff}; roster evidence available {r.eligibility_available_at}. No live injury or route-participation claims."
        )
        with st.expander(
            "Supplied-line research calculator — experimental probabilities"
        ):
            line = st.number_input(
                "Your line (default is hypothetical)",
                value=float(r.hypothetical_line),
                step=0.5,
                key="season_intel_line",
            )
            bundle = joblib.load(DEFAULT / "sunday_models.joblib")
            p = bundle["laws"][r.market].price(
                r.research_point, r.position, MARKETS[r.market][3], line
            )
            st.write(
                f"Over {p['over']:.1%} · Under {p['under']:.1%} · Push {p['push']:.1%}"
            )
            st.write(
                f"Refund-push fair decimal odds: Over {p['fair_over'] if p['fair_over'] else 'unavailable'}; Under {p['fair_under'] if p['fair_under'] else 'unavailable'}."
            )
            side = st.selectbox(
                "Quoted side", ["over", "under"], key="season_intel_side"
            )
            odds = st.number_input(
                "Actual decimal odds you supplied (leave empty without a quote)",
                min_value=1.01,
                value=None,
                key="season_intel_odds",
            )
            refund = st.checkbox(
                "I confirmed full-stake refund settlement for an integer-line push",
                key="season_intel_refund",
            )
            if odds is not None:
                if float(line).is_integer() and not refund:
                    st.info(
                        "Confirm settlement rules before calculating integer-line EV."
                    )
                else:
                    value = quoted_value(p, odds, side)
                    st.write(
                        f"Quoted break-even conditional probability {value['break_even_conditional']:.1%}; experimental expected profit per unit {value['expected_profit_per_unit']:+.3f}."
                    )
                    st.caption(
                        "This is an unvalidated research estimate using your supplied quote, not a betting recommendation or a verified available price."
                    )
